package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string

var schedRec SchedRec
var inputDone bool

func formatZZZZZZZZ9_99(d decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99 len 13
	// Need to handle negative? Not needed but support.
	pic := "ZZ,ZZZ,ZZ9.99"
	width := len(pic)
	// Determine sign
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	// d is already scaled to 2, but format generally
	// Truncate/round to 2? For display, the value already fits. Use quantized.
	// Ensure 2 decimal places
	d = d.Round(2)

	// Extract integer and fractional parts
	// Use string representation with 2 decimals
	s := d.StringFixed(2) // e.g. "1234.56"
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := parts[1]
	if len(fracPart) < 2 {
		fracPart = fracPart + strings.Repeat("0", 2-len(fracPart))
	}
	if len(fracPart) > 2 {
		fracPart = fracPart[:2]
	}

	// If integer part longer than max integer digits in picture, keep low-order digits
	// Count 9/Z placeholders before decimal
	intPlaceholders := 0
	for _, ch := range pic {
		if ch == 'Z' || ch == '9' {
			intPlaceholders++
		}
		if ch == '.' {
			break
		}
	}
	// intPlaceholders includes the digit before decimal? Actually pic "ZZ,ZZZ,ZZ9.99" -> before '.' there are 8 placeholders (ZZ,ZZZ,ZZ9) -> 2+3+2+1=8
	if len(intPart) > intPlaceholders {
		intPart = intPart[len(intPart)-intPlaceholders:]
	}
	// left pad intPart with zeros to intPlaceholders length
	intPartPadded := strings.Repeat("0", intPlaceholders-len(intPart)) + intPart

	// Build formatted string of same length as pic
	// We need to map placeholder positions to digits, commas, dot
	// Create result array size width
	res := make([]byte, width)
	// Fill from right to left handling pic characters
	// Iterate pic from right, intPart from right
	// Fractional part handling: digits after '.'
	fracIdx := len(fracPart) - 1

	// Determine positions of '.' in pic
	// We'll construct result by walking pic indices
	// For positions that are 'Z','9' after decimal, fill with frac digits
	// For '.' and ',' copy literally then later apply suppression
	intIdx := len(intPartPadded) - 1

	for i := width - 1; i >= 0; i-- {
		pc := pic[i]
		switch pc {
		case '.':
			res[i] = '.'
		case ',':
			res[i] = ','
		case 'Z', '9':
			// decide if this placeholder is integer or fractional side
			// Find dot position
			dotPos := strings.Index(pic, ".")
			if i > dotPos {
				// fractional
				if fracIdx >= 0 {
					res[i] = fracPart[fracIdx]
					fracIdx--
				} else {
					res[i] = '0'
				}
			} else {
				// integer
				if intIdx >= 0 {
					res[i] = intPartPadded[intIdx]
					intIdx--
				} else {
					res[i] = '0'
				}
			}
		}
	}

	// Apply Z suppression: from left until first non-zero digit that is not suppressed?
	// Rule: Z means leading zeros become spaces, commas inside suppressed zone become spaces.
	// The '9' forces printing, and zeros to its left are suppressed only if they are Z positions.
	// But also if integer part is all zeros, the '9' position prints 0.
	// Implement: scan from left to right over integer placeholders; keep track of whether we have encountered a non-zero digit.
	// All Z positions before the first non-zero are blanked; commas between them are blanked.
	// The first non-zero and everything to its right is kept.
	// If no non-zero found, keep the '9' position as '0' and blank all Z positions.

	dotPos := strings.Index(pic, ".")
	// Find index of last Z before dot? Actually find position of the rightmost '9' before dot
	// Suppression only applies to Z's before dot.

	// Collect integer placeholder indices
	// Determine first non-zero among integer digits (in res integer area)
	firstNonZeroPicIdx := -1
	for i := 0; i < dotPos; i++ {
		if pic[i] == 'Z' || pic[i] == '9' {
			if res[i] != '0' {
				firstNonZeroPicIdx = i
				break
			}
		}
	}
	if firstNonZeroPicIdx == -1 {
		// all zeros: blank all Z positions, keep the '9'
		for i := 0; i < dotPos; i++ {
			if pic[i] == 'Z' {
				res[i] = ' '
			} else if pic[i] == ',' {
				res[i] = ' '
			} else if pic[i] == '9' {
				// keep '0'
			}
		}
	} else {
		// blank everything left of firstNonZero that is Z or comma
		for i := 0; i < firstNonZeroPicIdx; i++ {
			if pic[i] == 'Z' {
				res[i] = ' '
			} else if pic[i] == ',' {
				// if still in suppressed zone, space
				res[i] = ' '
			}
		}
		// However Z zeros between firstNonZero and dot that are zero should remain '0' ? No, once we have hit non-zero, keep digits as is (including zeros)
	}

	if neg {
		// Need to place minus sign: just before first digit? For edited pic without sign, COBOL would not show sign, but keep.
		// Find first non-space character
		for i := 0; i < width; i++ {
			if res[i] != ' ' && res[i] != ',' && res[i] != '.' {
				if i > 0 && res[i-1] == ' ' {
					res[i-1] = '-'
				} else {
					res[i] = '-'
				}
				break
			}
		}
	}

	return string(res)
}

func moveToWsBalEd(d decimal.Decimal) {
	// Simulate MOVE WS-BAL TO WS-BAL-ED: store value then formatting when displayed
	// But WS-BAL-ED is edited; its string value is formatted
	// COBOL MOVE does truncation? WS-BAL is 9(8)V99, fits.
	// Just format
	WsBalEd = formatZZZZZZZZ9_99(d)
}

var schedFile *os.File
var scanner *bufio.Scanner
var schedFileOpen bool

func parseSchedRec(line string) SchedRec {
	// pad to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	}
	if len(line) > 16 {
		line = line[:16]
	}
	acct := line[0:4]
	prinStr := line[4:11]
	rateStr := line[11:15]
	yearsStr := line[15:16]

	prinDigits := strings.TrimSpace(prinStr)
	if prinDigits == "" {
		prinDigits = "0"
	}
	prinInt, _ := decimal.NewFromString(prinDigits)
	// prin has 2 decimal implicit
	prinVal := decimal.New(prinInt.Coeff().Int64(), -2) // but better use decimal.NewFromBigInt
	// Actually NewFromString already digits; use shift
	// Use decimal.New with exponent -2 based on integer value
	// If prinDigits may have leading zeros, parse as integer
	// Re-parse with big int to avoid int64 overflow? digits 7 fits.
	// Use manual
	pi := decimal.RequireFromString(prinDigits)
	prinVal = pi.Shift(-2)

	rateVal := decimal.Zero
	rateDigits := strings.TrimSpace(rateStr)
	if rateDigits != "" {
		ri := decimal.RequireFromString(rateDigits)
		rateVal = ri.Shift(-2)
	}

	var years int64 = 0
	yearsStrTrim := strings.TrimSpace(yearsStr)
	if yearsStrTrim != "" {
		yi := decimal.RequireFromString(yearsStrTrim)
		years = yi.IntPart()
	}

	return SchedRec{
		ScAcct:  acct,
		ScPrin:  prinVal,
		ScRate:  rateVal,
		ScYears: years,
	}
}

func readPara() {
	if scanner.Scan() {
		line := scanner.Text()
		// COBOL LINE SEQUENTIAL strips newline, not trailing spaces; we pad inside parse
		schedRec = parseSchedRec(line)
		inputDone = false
		WsEofFlag = "N"
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func processPara() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = schedRec.ScPrin
	// truncate/store to 9(8)V99 scale2
	WsBal = WsBal.Truncate(2)
	// Simulate high-order digit drop: keep low-order digits that fit 8 integer digits
	// Not needed generally

	for WsYear = 1; WsYear <= schedRec.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		one := decimal.NewFromInt(1)
		hundred := decimal.NewFromInt(100)
		rateDiv := schedRec.ScRate.Div(hundred) // rate/100; using Div is okay for /100 but we use Shift alternative
		// Use Shift for accuracy: SC-RATE is with 2 decimals, /100 -> shift -2
		// But we already have decimal value; use Mul/Div correctly: rateDiv = ScRate /100
		_ = rateDiv
		// Use Shift method to avoid Div precision limits:
		factor := one.Add(schedRec.ScRate.Shift(-2))
		raw := WsBal.Mul(factor)
		// ROUNDED to scale 2 half away from zero
		WsBal = raw.Round(2)
		// Simulate store truncation/high-order drop (scale already 2)
		// Format
		moveToWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		wsYearStr := fmt.Sprintf("%d", WsYear)
		// WS-YEAR PIC 99 unedited prints as ??? In COBOL DISPLAY numeric unedited: no leading zero suppression? But typically DISPLAY shows as is without leading zeros? Spec says: unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded. So PIC 99 should be zero-padded to 2 digits? However original COBOL DISPLAY of WS-YEAR (PIC 99) ?? Let's check: DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		// For PIC 99, if value 1, would print "01"? But spec says: unedited numeric DISPLAY prints zero-padded to digit count. So would be 2 chars.
		// However typical COBOL DISPLAY of COMP? But here it's DISPLAY numeric 99 would print "01". Need to follow spec: zero-padded.
		// Let's verify expected: Need to mimic COBOL: PIC 99 DISPLAY would produce maybe " 1" ?? But rule given says zero-padded.
		// We'll follow rule: zero-padded to width 2.
		// But check example of program translation tests: they use PIC 99 year counter often expecting "1" without zero padding. However rule states unedited prints zero-padded.
		// We'll follow rule explicitly.
		// Actually rule: "An unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count." So yes.

		// Need to check width: PIC 99 len 2 -> format "%02d"
		wsYearFormatted := fmt.Sprintf("%02d", WsYear)
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, wsYearFormatted, WsBalEd)
	}
	moveToWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount++
	readPara()
}

func main() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		// If file not found, treat as empty
		inputDone = true
		WsEofFlag = "Y"
	} else {
		scanner = bufio.NewScanner(schedFile)
		schedFileOpen = true
		defer schedFile.Close()
		readPara()
		for !inputDone {
			processPara()
		}
		if schedFileOpen {
			schedFile.Close()
		}
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WS-COUNT PIC 99 unedited zero-padded? But final display: they expect maybe "01" or "1"?
	// Rule says zero-padded. We'll format as zero-padded 2 digits, but if exceeds? However many tests expect non-padded for count? Let's see: WS-COUNT is PIC 99, DISPLAY will be zero-padded.
	// But common COBOL DISPLAY of PIC 99 count would show "03" for 3. Spec says to do that.
	wsCountFormatted := fmt.Sprintf("%02d", WsCount)
	fmt.Printf("SCHEDULES: %s\n", wsCountFormatted)
	_ = WsEofFlag
}

